macro_rules! deps {
    () => {
        ReadVectoredFuture!();
        Cursor!();
        ReadFuture!();
        ReadToStringFuture!();
        ReadToEndFuture!();
        ReadExactFuture!();
    };
}

macro_rules! AsyncReadExt {
    () => {
        deps!();
        # [doc = " Extension trait for [`AsyncRead`]."] pub trait AsyncReadExt : AsyncRead { # [doc = " Reads some bytes from the byte stream."] # [doc = ""] # [doc = " On success, returns the total number of bytes read."] # [doc = ""] # [doc = " If the return value is `Ok(n)`, then it must be guaranteed that"] # [doc = " `0 <= n <= buf.len()`. A nonzero `n` value indicates that the buffer has been"] # [doc = " filled with `n` bytes of data. If `n` is `0`, then it can indicate one of two"] # [doc = " scenarios:"] # [doc = ""] # [doc = " 1. This reader has reached its \"end of file\" and will likely no longer be able to"] # [doc = "    produce bytes. Note that this does not mean that the reader will always no"] # [doc = "    longer be able to produce bytes."] # [doc = " 2. The buffer specified was 0 bytes in length."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, BufReader};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let input: &[u8] = b\"hello\";"] # [doc = " let mut reader = BufReader::new(input);"] # [doc = ""] # [doc = " let mut buf = vec![0; 1024];"] # [doc = " let n = reader.read(&mut buf).await?;"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn read < 'a > (& 'a mut self , buf : & 'a mut [u8]) -> ReadFuture < 'a , Self > where Self : Unpin , { ReadFuture { reader : self , buf } } # [doc = " Like [`read()`][`AsyncReadExt::read()`], except it reads into a slice of buffers."] # [doc = ""] # [doc = " Data is copied to fill each buffer in order, with the final buffer possibly being"] # [doc = " only partially filled. This method must behave same as a single call to"] # [doc = " [`read()`][`AsyncReadExt::read()`] with the buffers concatenated would."] fn read_vectored < 'a > (& 'a mut self , bufs : & 'a mut [IoSliceMut < 'a >] ,) -> ReadVectoredFuture < 'a , Self > where Self : Unpin , { ReadVectoredFuture { reader : self , bufs } } # [doc = " Reads the entire contents and appends them to a [`Vec`]."] # [doc = ""] # [doc = " On success, returns the total number of bytes read."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let mut reader = Cursor::new(vec![1, 2, 3]);"] # [doc = " let mut contents = Vec::new();"] # [doc = ""] # [doc = " let n = reader.read_to_end(&mut contents).await?;"] # [doc = " assert_eq!(n, 3);"] # [doc = " assert_eq!(contents, [1, 2, 3]);"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn read_to_end < 'a > (& 'a mut self , buf : & 'a mut Vec < u8 >) -> ReadToEndFuture < 'a , Self > where Self : Unpin , { let start_len = buf . len () ; ReadToEndFuture { reader : self , buf , start_len , } } # [doc = " Reads the entire contents and appends them to a [`String`]."] # [doc = ""] # [doc = " On success, returns the total number of bytes read."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let mut reader = Cursor::new(&b\"hello\");"] # [doc = " let mut contents = String::new();"] # [doc = ""] # [doc = " let n = reader.read_to_string(&mut contents).await?;"] # [doc = " assert_eq!(n, 5);"] # [doc = " assert_eq!(contents, \"hello\");"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn read_to_string < 'a > (& 'a mut self , buf : & 'a mut String) -> ReadToStringFuture < 'a , Self > where Self : Unpin , { ReadToStringFuture { reader : self , buf , bytes : Vec :: new () , start_len : 0 , } } # [doc = " Reads the exact number of bytes required to fill `buf`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let mut reader = Cursor::new(&b\"hello\");"] # [doc = " let mut contents = vec![0; 3];"] # [doc = ""] # [doc = " reader.read_exact(&mut contents).await?;"] # [doc = " assert_eq!(contents, b\"hel\");"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn read_exact < 'a > (& 'a mut self , buf : & 'a mut [u8]) -> ReadExactFuture < 'a , Self > where Self : Unpin , { ReadExactFuture { reader : self , buf } } # [doc = " Creates an adapter which will read at most `limit` bytes from it."] # [doc = ""] # [doc = " This method returns a new instance of [`AsyncRead`] which will read at most"] # [doc = " `limit` bytes, after which it will always return `Ok(0)` indicating EOF."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let mut reader = Cursor::new(&b\"hello\");"] # [doc = " let mut contents = String::new();"] # [doc = ""] # [doc = " let n = reader.take(3).read_to_string(&mut contents).await?;"] # [doc = " assert_eq!(n, 3);"] # [doc = " assert_eq!(contents, \"hel\");"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn take (self , limit : u64) -> Take < Self > where Self : Sized , { Take { inner : self , limit } } # [doc = " Converts this [`AsyncRead`] into a [`Stream`] of bytes."] # [doc = ""] # [doc = " The returned type implements [`Stream`] where `Item` is `io::Result<u8>`."] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = " use futures_lite::stream::StreamExt;"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let reader = Cursor::new(&b\"hello\");"] # [doc = " let mut bytes = reader.bytes();"] # [doc = ""] # [doc = " while let Some(byte) = bytes.next().await {"] # [doc = "     println!(\"byte: {}\", byte?);"] # [doc = " }"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn bytes (self) -> Bytes < Self > where Self : Sized , { Bytes { inner : self } } # [doc = " Creates an adapter which will chain this stream with another."] # [doc = ""] # [doc = " The returned [`AsyncRead`] instance will first read all bytes from this reader"] # [doc = " until EOF is found, and then continue with `next`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::{AsyncReadExt, Cursor};"] # [doc = ""] # [doc = " # spin_on::spin_on(async {"] # [doc = " let r1 = Cursor::new(&b\"hello\");"] # [doc = " let r2 = Cursor::new(&b\"world\");"] # [doc = " let mut reader = r1.chain(r2);"] # [doc = ""] # [doc = " let mut contents = String::new();"] # [doc = " reader.read_to_string(&mut contents).await?;"] # [doc = " assert_eq!(contents, \"helloworld\");"] # [doc = " # std::io::Result::Ok(()) });"] # [doc = " ```"] fn chain < R : AsyncRead > (self , next : R) -> Chain < Self , R > where Self : Sized , { Chain { first : self , second : next , done_first : false , } } # [doc = " Boxes the reader and changes its type to `dyn AsyncRead + Send + 'a`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use futures_lite::io::AsyncReadExt;"] # [doc = ""] # [doc = " let reader = [1, 2, 3].boxed_reader();"] # [doc = " ```"] # [cfg (feature = "alloc")] fn boxed_reader < 'a > (self) -> Pin < Box < dyn AsyncRead + Send + 'a > > where Self : Sized + Send + 'a , { Box :: pin (self) } }
    };
}

AsyncReadExt!();